-- SQL Backfill untuk mengisi deskripsi resep menggunakan DeepSeek V4 Pro

UPDATE public.recipes SET description = 'Renyah di luar, juicy di dalam, ayam goreng ini dipenuhi aroma bawang putih goreng yang gurih dan harumnya bumbu rempah pilihan. Sekali gigit, sensasi kriuknya langsung bikin seluruh keluarga ketagihan dan minta nambah lagi.' WHERE id = 8;
UPDATE public.recipes SET description = 'Ayam goreng renyah berpadu sempurna dengan siraman saus kecap manis gurih, wangi jahe, dan tumisan bawang bombay yang menggugah selera. Tambahan iris cabai merah dan daun bawang segar memberikan sentuhan pedas ringan dan aroma yang langsung membangkitkan semangat makan keluarga. Dijamin jadi menu favorit yang membuat nasi cepat habis!' WHERE id = 9;
UPDATE public.recipes SET description = 'Nikmati semangkuk mie kenyal berpadu sempurna dengan topping ayam berbumbu kecap legit yang dimasak bersama rempah pilihan, menghadirkan aroma menggoda dan cita rasa gurih manis yang sulit dilupakan. Kuah kaldu hangatnya melengkapi setiap suapan, menjadikan Mie Ayam ini santapan praktis dan istimewa yang pasti disukai seluruh anggota keluarga.' WHERE id = 10;
UPDATE public.recipes SET description = 'Malam ini, hadirkan kehangatan di meja makan dengan trio tumis spesial: pokcoy renyah yang dimasak kilat bersama harum bawang putih, ayam bawang putih yang dimarinasi lama hingga juicy dan sedikit gosong menggugah selera, serta tumis bawang merah pedas manis yang melengkapi hidangan. Santapan sederhana namun kaya rasa ini dijamin bikin seluruh keluarga lahap menambah nasi!' WHERE id = 11;
UPDATE public.recipes SET description = 'Nikmati kelezatan Ayam Woku Manado dengan bumbu rempah pilihan yang meresap sempurna, menghadirkan sensasi pedas segar yang menggoda. Perpaduan ayam empuk, kuah kunyit yang harum, dan kemangi wangi siap memanjakan lidah sekaligus menghangatkan kebersamaan di meja makan keluarga.' WHERE id = 12;
UPDATE public.recipes SET description = 'Potongan ayam juicy berpadu sempurna dengan siraman kecap manis legit dan sentuhan pedas cabai merah yang menggoda, menghadirkan aroma tumisan bawang putih yang langsung membangkitkan selera. Sajikan hangat dengan taburan daun bawang segar, dijamin seluruh keluarga rebutan nambah nasi!' WHERE id = 14;
UPDATE public.recipes SET description = 'Ayam Goreng Madu Pedes hadir dengan balutan tepung renyah yang bertemu siraman saus madu pedas legit, menciptakan ledakan rasa manis gurih dan sedikit asam segar. Aroma tumisan bawang putih berpadu dengan karamel madu yang menggoda, siap membuat seluruh anggota keluarga rebutan nambah nasi hangat.' WHERE id = 15;
UPDATE public.recipes SET description = 'Kalio Ati Ampela Ayam menghadirkan kelezatan ati yang lembut dan ampela yang kenyal, dimasak perlahan dalam rempah pilihan dan santan kental yang meresap hingga ke seratnya. Setiap suapan menawarkan paduan gurih, pedas hangat yang pas, dan aroma serai serta daun jeruk yang membangkitkan selera, cocok disantap bersama nasi hangat untuk momen makan keluarga yang istimewa.' WHERE id = 16;
UPDATE public.recipes SET description = 'Bayangkan kelembutan bakso ayam buatan sendiri yang kenyal ringan, dibuat dari daging ayam segar dan paduan bawang goreng yang harumnya langsung mengundang seluruh keluarga berkumpul. Disiram kuah kaldu bening yang gurih hangat dengan taburan daun seledri dan bawang goreng renyah, setiap suap terasa begitu menenangkan dan bikin nagih. Sajian rumahan sederhana ini selalu sukses menghadirkan senyum di meja makan.' WHERE id = 18;
UPDATE public.recipes SET description = 'Renyah di luar, lumer di dalam! Roti goreng keemasan ini menyembunyikan isian ragout ayam, wortel, dan kentang yang creamy, gurih susu, serta wangi pala menggoda. Camilan hangat yang bikin seluruh keluarga lahap dan ingin lagi!' WHERE id = 19;
UPDATE public.recipes SET description = 'Renyah garing di luar, namun tetap juicy di dalam, Ayam Goreng Terasi ala Resto ini memadukan gurih khas terasi sangrai dengan bumbu bawang, jahe, dan kecap yang meresap sempurna hingga ke tulang. Aromanya begitu menggoda, dijamin seluruh keluarga langsung berebut dan menjadikan menu ini favorit baru di rumah!' WHERE id = 20;
UPDATE public.recipes SET description = 'Nasi Tim Ayam yang lembut dan hangat ini menyajikan nasi pulen gurih bersama ayam manis legit berbalut kuah kental beraroma jahe, lengkap dengan telur rebus yang nyaman di perut. Setiap suapan bagaikan pelukan hangat untuk seluruh keluarga, sempurna dinikmati kapan saja terutama saat ingin makanan rumahan yang menenangkan.' WHERE id = 21;
UPDATE public.recipes SET description = 'Bubur Ayam Kuah Kuning hangat ini menyajikan perpaduan sempurna bubur nasi lembut, kuah kaldu ayam bersantan yang gurih meresap, dan suwiran ayam goreng renyah. Lengkap dengan sate telur puyuh manis, cakwe, kerupuk, dan sambal pedas, semangkuk istimewa ini selalu sukses membangunkan selera seluruh keluarga di pagi hari.' WHERE id = 22;
UPDATE public.recipes SET description = 'Sajian Kung Pao Chicken ini memadukan potongan ayam renyah berlapis saus pedas manis yang legit, lengkap dengan gurihnya kacang mede dan segarnya paprika. Sekali suap, perpaduan rasa gurih, manis, dan sedikit pedasnya dijamin bikin seluruh keluarga ketagihan dan nambah nasi terus!' WHERE id = 23;
UPDATE public.recipes SET description = 'Nikmati kelembutan paha ayam juicy yang dimasak dengan mentega harum, menciptakan steak rumahan istimewa yang ramah di lidah seluruh anggota keluarga. Perpaduan saus manis gurih dari kecap asin premium dan sentuhan segar jeruk limo memberikan cita rasa kaya yang menggoda selera. Sajikan hangat dengan siraman saus kental mengilap, siap menjadi menu favorit di meja makan Anda!' WHERE id = 24;
UPDATE public.recipes SET description = 'Soto Ayam Ambengan menghadirkan semangkuk kehangatan penuh rempah dengan kuah kuning gurih yang meresap lembut ke setiap potongan ayam kampung empuk. Dilengkapi taburan daun bawang, seledri segar, dan bawang goreng renyah, soto ini semakin istimewa saat disantap bersama perkedel, nasi putih hangat, serta perasan jeruk nipis yang menyegarkan. Sajian lengkap yang selalu dirindukan dan cocok menyatukan cita rasa keluarga di meja makan.' WHERE id = 26;
UPDATE public.recipes SET description = 'Siapa bilang camilan enak tak bisa sehat? Nugget ayam wortel buatan sendiri ini menghadirkan kelembutan daging ayam giling berpadu manisnya wortel segar, menjadikannya favorit baru seluruh keluarga. Dibalut tepung panir yang renyah keemasan, setiap gigitan adalah kelezatan gurih tanpa pengawet yang aman untuk bekal sekolah atau teman bersantai.' WHERE id = 27;
UPDATE public.recipes SET description = 'Renyah keemasan puff pastry berpadu sempurna dengan isian tuna pedas gurih dan potongan telur rebus yang lembut—camilan kilat andalan untuk seluruh keluarga! Hanya butuh waktu sekejap, suguhan lezat ini siap memanjakan hari Anda.' WHERE id = 28;
UPDATE public.recipes SET description = 'Segarnya kuah asam dari belimbing wuluh dan tomat hijau berpadu dengan pedasnya cabai rawit, menyatu sempurna dengan kelembutan ikan tenggiri segar. Racikan rempah serai, jahe, dan kunyit menghadirkan kehangatan yang membuat makan bersama keluarga semakin istimewa.' WHERE id = 29;
UPDATE public.recipes SET description = 'Nikmati sensasi gurih renyah Pindang Tongkol Suwir yang digoreng kering, lalu berpadu sempurna dengan sambal matah segar beraroma wangi sereh, daun jeruk, dan ledakan pedas cabe kecil. Siraman air jeruk limau dan minyak kelapa membuat setiap suapan terasa seimbang, asam segar yang membangkitkan selera seluruh keluarga.' WHERE id = 30;
UPDATE public.recipes SET description = 'Kalio Tenggiri memadukan kelembutan ikan tenggiri segar dengan kuah santan kuning kental yang gurih berempah, menciptakan aroma sereh dan daun jeruk yang langsung membangkitkan selera. Potongan wortel renyah dan sentuhan pedas cabe utuh menghadirkan kehangatan rumahan yang sempurna, mengundang seluruh keluarga segera bersantap bersama.' WHERE id = 32;
UPDATE public.recipes SET description = 'Nikmati sensasi segar pedas asam yang langsung menggoyang lidah dari Ikan Tongkol Asem Padeh Istimewa ini. Potongan ikan tongkol yang lembut berpadu sempurna dengan kuah merah merona, kaya rempah serai, daun jeruk, dan asam kandis yang bikin ketagihan. Hidangan sederhana bumbu halus ini dijamin bikin makan siang keluarga jadi istimewa dan penuh kehangatan.' WHERE id = 33;
UPDATE public.recipes SET description = 'Lapisan puff pastry yang super renyah berpadu sempurna dengan isian tuna dan jamur kancing gurih yang dimasak dengan bumbu aromatik, lalu dilengkapi lelehan keju cheddar di setiap gigitannya. Camilan hangat yang praktis dan kaya rasa ini pasti jadi rebutan seluruh anggota keluarga, apalagi dicocol saus sambal dan mayones.' WHERE id = 34;
UPDATE public.recipes SET description = 'Nikmati sensasi kenyal dan gurihnya Pempek Tenggiri asli Palembang, dengan isian telur lembut yang lumer di mulut! Siraman cuko asam manis pedas buatan sendiri langsung membangkitkan selera, membuat setiap gigitan terasa segar dan nagih. Sajian istimewa yang akan membuat momen kumpul keluarga semakin hangat dan penuh tawa!' WHERE id = 35;
UPDATE public.recipes SET description = 'Ikan gurami goreng yang gurih berpadu sempurna dengan siraman saus tiram pedas manis yang kental dan menggoda, menciptakan hidangan istimewa yang langsung membangkitkan selera seluruh anggota keluarga. Aroma harum jahe, daun jeruk, dan tumisan bawang membuat setiap suapan terasa hangat dan tak terlupakan.' WHERE id = 36;
UPDATE public.recipes SET description = 'Hadirkan kehangatan di meja makan dengan semangkuk Ikan Nila Kuah Pindang yang menggoda—kuah kuningnya yang gurih dan aromatik memeluk lembut daging ikan nila, ditambah percikan pedas dari cabe rawit utuh dan kesegaran asam dari irisan tomat. Setiap tegukan kuahnya terasa ringan namun kaya rasa, dijamin membuat seluruh keluarga lahap menyantapnya bersama nasi putih hangat.' WHERE id = 37;
UPDATE public.recipes SET description = 'Nikmati perpaduan istimewa gurih lembut ikan tongkol dan kenyal nikmat jengkol yang terselimuti sambal balado merah pedas, aromanya langsung membangkitkan selera seisi rumah. Hidangan tradisional favorit keluarga ini siap jadi lauk andalan, bikin nasi putih hangat selalu nambah!' WHERE id = 38;
UPDATE public.recipes SET description = 'Nikmati sensasi renyahnya ikan gurame goreng keemasan yang diselimuti sambal pecak segar nan pedas—perpaduan gurih ikan, asam dari asam jawa, dan wangi rempah serai serta kencur benar-benar membangkitkan selera. Sajian istimewa ini pas sekali jadi menu favorit keluarga di akhir pekan, dijamin bikin seluruh anggota keluarga berebut nambah nasi hangat!' WHERE id = 40;
UPDATE public.recipes SET description = 'Nikmati pizza homemade yang renyah di luar dan lembut di dalam dengan paduan gurih tuna kalengan serta manisnya jagung pipil yang kaya serat. Aroma oregano dan saus bolognese meresap sempurna, sementara keju mozarella yang meleleh memberi sensasi lezat di setiap gigitan. Sajikan hangat-hangat sebagai camilan istimewa yang sehat, mudah dibuat, dan pasti disukai seluruh anggota keluarga.' WHERE id = 41;
UPDATE public.recipes SET description = 'Ikan mujair goreng renyah berpadu sempurna dengan siraman oseng cabe segar yang pedas, gurih, dan sedikit manis menggoda. Aroma tumisan bawang dan cabe yang menguar hangat pasti bikin seluruh keluarga lahap menyantapnya dengan nasi putih mengepul.' WHERE id = 42;
UPDATE public.recipes SET description = 'Suwiran pindang tongkol pedas ini memadukan harum rempah sereh, lengkuas, dan daun jeruk yang membangkitkan selera makan keluarga. Bumbu kuning gurih meresap sempurna ke setiap serat ikan, menghadirkan sensasi pedas menggigit yang bikin nagih, paling pas disantap dengan nasi hangat yang mengepul.' WHERE id = 44;
UPDATE public.recipes SET description = 'Ikan kembung goreng garing disiram tumisan cabe ijo, bawang, dan perasan jeruk limo yang segar menggoda selera. Tanpa perlu repot ngulek, resep bedinde ini mudah dibuat tapi hasilnya luar biasa nikmat—apalagi ditambah pete yang memberi sensasi kletus-kletus bikin makan siang jadi istimewa.' WHERE id = 45;
UPDATE public.recipes SET description = 'Paduan gurih lembut salmon panggang dadu yang juicy dengan nasi goreng kecap manis beraroma bawang tumis ini langsung membangunkan selera seisi rumah. Sensasi gurih alami ikan berpadu legit manis dalam tiap suapan hangatnya, jadi menu sarapan atau makan malam bernutrisi yang bikin keluarga nambah terus.' WHERE id = 46;
UPDATE public.recipes SET description = 'Nikmati semangkuk Gulai Ikan Tuna berwarna kuning keemasan yang menggoda, dengan potongan tuna empuk yang meresap dalam kuah santan lembut dan rempah pilihan. Aroma segar dari perasan jeruk lemon dan daun jeruk berpadu sempurna dengan gurihnya santan, ditambah potongan kacang panjang renyah dan tomat segar yang membuat setiap suapan terasa semakin kaya. Sajian hangat yang selalu dinanti seluruh anggota keluarga, dijamin bikin nambah terus!' WHERE id = 47;
UPDATE public.recipes SET description = 'Tahu Aci hadir dengan kulit tahu yang renyah di luar, namun begitu digigit langsung lumer oleh isian aci yang kenyal dan gurih kaya aroma bawang putih serta daun bawang. Cocolkan ke sambal kecap pedas yang manis segar, camilan sederhana ini langsung jadi rebutan seluruh anggota keluarga. Cemilan rumahan yang bikin kumpul sore makin hangat dan tak terlupakan!' WHERE id = 57;
UPDATE public.recipes SET description = 'Renyah di luar, kenyal di dalam, bola tahu aci ini berselimut saus pedas manis yang bikin seluruh keluarga ketagihan. Sajian hangat yang menggoda dan mudah dicintai, sempurna untuk melengkapi keceriaan meja makan Anda.' WHERE id = 58;
UPDATE public.recipes SET description = 'Sajikan kehangatan di meja makan dengan sup bening beraroma jahe dan minyak wijen yang menenangkan, diisi bakso ayam lembut dengan kejutan tekstur renyah jamur enoki di setiap gigitan. Perpaduan tahu sutra, wortel manis, dan irisan kubis segar dalam kuah kaldu gurih alami membuat setiap seruputannya begitu nikmat dan menyehatkan. Cukup satu mangkuk besar bersama nasi hangat, semangkuk penuh cinta siap menghangatkan hari seluruh keluarga.' WHERE id = 59;
UPDATE public.recipes SET description = 'Nikmati kelembutan tahu kulit yang menyerap sempurna bumbu kecap manis legit dan gurih, berpadu dengan aroma tumisan bawang, cabe, dan kemiri yang menggoda selera. Lauk simpel yang hangat dan meresap ini dijamin jadi rebutan keluarga di meja makan!' WHERE id = 61;
UPDATE public.recipes SET description = 'Nikmati kehangatan Sundubu Jjigae, sup tahu pedas ala Korea yang memadukan tahu lembut, tauge segar, dan kuah merah menggoda dengan sentuhan asam jeruk nipis. Setiap suapan menghadirkan kelezatan gurih pedas yang ramah di lidah, sempurna menghangatkan momen makan bersama keluarga. Mudah dibuat dengan bumbu halus pilihan, hidangan ini siap menjadi favorit baru di meja makan Anda.' WHERE id = 62;
UPDATE public.recipes SET description = 'Tahu Fantasy hadir sebagai camilan sehat nan lezat, memadukan kelembutan tahu Bandung dan bihun jagung dengan manisnya wortel segar serta gurihnya telur. Dikukus dulu agar padat dan lembut di dalam, lalu digoreng hingga kuning keemasan yang menghadirkan sensasi renyah di luar namun tetap moist di dalam. Sajian simpel yang penuh gizi ini pasti bikin seluruh keluarga ketagihan di setiap gigitan!' WHERE id = 63;
UPDATE public.recipes SET description = 'Tahu lembut berpadu ayam dan wortel, dipangku manisnya sosis yang membentuk mahkota renyah di setiap gigitan—luar garing, dalamnya lumer penuh rasa. Camilan seru favorit keluarga, bikin si kecil lahap dan semua ingin tambah lagi!' WHERE id = 64;
UPDATE public.recipes SET description = 'Tahu goreng renyah berpadu sempurna dengan siraman saus kuning telur asin yang creamy dan gurih, ditambah sentuhan pedas cabe yang menggoda. Setiap gigitannya langsung meleleh di mulut, bikin makan siang atau malam keluarga jadi momen istimewa. Satu gigitan saja pasti bikin seluruh keluarga nambah lagi dan lagi!' WHERE id = 65;
UPDATE public.recipes SET description = 'Renyah di luar, lumer di dalam! Bola-bola tahu gurih ini menyembunyikan kejutan isian sosis dan keju meleleh yang bikin nagih. Camilan favorit keluarga yang mudah dibuat, pas buat temani hari-hari ceria si kecil sampai acara kumpul spesial di rumah.' WHERE id = 67;
UPDATE public.recipes SET description = 'Hangatnya kuah kare kuning yang kental berpadu sempurna dengan ayam empuk dan tahu goreng yang menyerap semua bumbu rempah. Aroma daun jeruk, serai, dan lengkuas yang ditumis harum akan langsung membangkitkan selera makan seluruh keluarga. Sajikan dengan nasi hangat, dan nikmati setiap suapan gurih santan yang meresap hingga ke tulang!' WHERE id = 68;
UPDATE public.recipes SET description = 'Renyahnya tahu goreng berpadu sempurna dengan gurihnya bumbu bawang putih dan pedas segar cabai rawit, menciptakan sajian yang bikin ketagihan. Aroma daun bawang menambah kelezatan, Tahu Cabe Garam ini paling nikmat disantap dengan nasi hangat bersama keluarga tercinta.' WHERE id = 69;
UPDATE public.recipes SET description = 'Tahu crispy renyah di luar, lembut di dalam, dengan bumbu bawang putih yang meresap hingga ke pori-pori tahu. Camilan simpel ini sungguh bikin ketagihan—gurih garingnya pas dinikmati hangat-hangat bersama keluarga, apalagi ditambah taburan bubuk cabai favorit.' WHERE id = 70;
UPDATE public.recipes SET description = 'Nikmati sensasi segar pedas manis Tahu Gejrot khas Cirebon, camilan sederhana yang bikin ketagihan! Tahu pong renyah disiram kuah ulek bawang dan cabai hijau berpadu gula merah serta perasan jeruk limau, melepas dahaga selera di setiap gigitan. Sajikan hangat untuk keluarga tercinta, dijamin ludes!' WHERE id = 71;
UPDATE public.recipes SET description = 'Rolade tahu sosis yang lembut dan gurih ini memadukan tahu putih padat, potongan sayur segar, dan sosis juicy dalam gulungan telur dadar yang pas di lidah seluruh anggota keluarga. Dikukus dengan daun pisang hingga aroma alaminya keluar, setiap irisannya langsung bikin semangat makan si kecil maupun dewasa. Sajikan hangat dengan cocolan sambal kecap favorit, dijamin jadi rebutan!' WHERE id = 72;
UPDATE public.recipes SET description = 'Siapa yang bisa menolak kelembutan tahu berpadu gurih telur dan daun bawang, lalu digoreng renyah keemasan? Siraman bumbu pecel pedas-manisnya langsung membangkitkan selera, menjadikan Batagor Tahu ini camilan sederhana yang selalu bikin semua anggota keluarga ketagihan.' WHERE id = 74;
UPDATE public.recipes SET description = 'Renyahnya tepung berbumbu berpadu sempurna dengan lembutnya telur dadar di dalam, menciptakan camilan kriuk yang bikin ketagihan. Sajian simpel dan gurih ini pas sekali menemani momen santai bersama keluarga tercinta.' WHERE id = 76;
UPDATE public.recipes SET description = 'Siapa sangka camilan legendaris ala angkringan ini bisa Anda buat sendiri di rumah dengan hasil super crispy dan bersarang sempurna? Sate Telur Gulung Crispy menghadirkan sensasi garing di luar, lembut gurih di dalam, lengkap dengan potongan sosis juicy yang bikin si kecil sampai orang dewasa susah berhenti ngunyah. Dengan trik cerdas menggoreng pakai rantang agar minyak lebih hemat, momen masak bersama keluarga jadi lebih seru dan pastinya anti gagal!' WHERE id = 77;
UPDATE public.recipes SET description = 'Telur ceplok renyah berpadu sempurna dengan tumisan tauco, cabai, dan tomat yang harum menggoda, menciptakan kuah gurih-manis dengan sentuhan pedas yang menyegarkan. Setiap suapan telur menyerap bumbu kecap dan tauco yang meresap dalam, begitu lembut di mulut dan pas dinikmati seluruh anggota keluarga. Sajian sederhana yang mampu membuat nasi putih di meja makan cepat habis tanpa sisa.' WHERE id = 78;
UPDATE public.recipes SET description = 'Paduan timun Jepang yang renyah segar dan telur orak-arik lembut gurih berpadu dalam cah harum jahe dan bawang putih. Sensasi ringan dengan sentuhan saus tiram yang menggoda, hidangan ini jadi teman makan siang yang begitu disukai keluarga.' WHERE id = 81;
UPDATE public.recipes SET description = 'Nikmati kelezatan roti tawar celup telur yang renyah di luar, lembut di dalam, dengan keju lumer dan potongan sosis yang menggoda di setiap gigitannya. Perpaduan tomat segar, daun bawang, dan sentuhan boncabe menciptakan sarapan simpel yang hangat dan bikin seisi rumah berebut minta tambah. Sajikan bareng mayones dan sambal biar momen santap pagi makin semarak!' WHERE id = 82;
UPDATE public.recipes SET description = 'Sajian sederhana yang selalu bikin semangat! Makaroni empuk berpadu gurihnya telur dan sensasi pedas balado yang menggoda, sempurna jadi camilan hangat favorit seluruh keluarga.' WHERE id = 83;
UPDATE public.recipes SET description = 'Telur rebus yang dimasak perlahan dalam racikan teh, gula merah, kecap manis, dan rempah pilihan menghasilkan Pindang Telur dengan warna cokelat gelap yang menggugah selera. Aroma serai dan daun salam yang harum berpadu dengan rasa manis gurih yang meresap sempurna hingga ke dalam telur, menjadikannya lauk favorit yang selalu dirindukan di meja makan keluarga.' WHERE id = 85;
UPDATE public.recipes SET description = 'Paduan tahu lembut dan telur gurih menciptakan dadar yang renyah di luar, namun lembut di dalam. Sentuhan pedas cabe merah dan aroma segar daun bawang menjadikannya lauk simpel yang selalu bikin nambah nasi. Cocok disajikan hangat untuk sarapan atau bekal si kecil, dijamin seluruh keluarga suka!' WHERE id = 86;
UPDATE public.recipes SET description = 'Sajian rumahan penuh warna ini memadukan telur orak-arik yang lembut dengan manis alami jagung, wortel, buncis, dan polong dalam setiap suapan. Aroma tumisan bawang yang harum dan sentuhan merica menciptakan hidangan hangat nan praktis, cocok untuk sarapan ceria maupun bekal yang disukai seluruh anggota keluarga.' WHERE id = 87;
UPDATE public.recipes SET description = 'Lembutnya tahu telur goreng berkulit bertemu brokoli renyah dan jamur kuping kenyal dalam balutan saus tiram gurih serta wangi minyak wijen yang menggoda. Tumisan rumahan sederhana penuh gizi ini siap jadi lauk favorit yang bikin seisi keluarga lahap menambah nasi.' WHERE id = 89;
UPDATE public.recipes SET description = 'Sajian sederhana yang selalu dirindukan ini memadukan kesegaran taoge yang renyah dengan potongan telur dadar lembut gurih dalam balutan saus tiram dan manisnya kecap. Aroma bawang dan cabe yang ditumis harum langsung membangkitkan selera, siap memeriahkan meja makan keluarga dengan kelezatan yang hangat dan menenangkan.' WHERE id = 91;
UPDATE public.recipes SET description = 'Nikmati kelembutan telur kukus tanpa tepung yang dipadu potongan sosis gurih dan manisnya wortel segar, menciptakan hidangan sehat nan ringan untuk seluruh keluarga. Disajikan dengan sambal kecap pedas menyegarkan, bikin setiap suapan terasa istimewa dan bikin nagih!' WHERE id = 92;
UPDATE public.recipes SET description = 'Telur rebus dan tahu kuning yang lembut berpadu dalam siraman kecap manis dan rempah pilihan, menghasilkan semur gurih manis yang meresap sempurna. Aroma hangat lengkuas dan daun salamnya bikin seisi rumah langsung kumpul, cocok jadi lauk andalan keluarga yang bikin nambah berkali-kali.' WHERE id = 93;
UPDATE public.recipes SET description = 'Casserole telur dan daging sapi ini memadukan lapisan telur lembut dengan tumisan daging cincang berbumbu tomat manis alami, lalu dimanjakan saus keju creamy yang meleleh di setiap suapan. Aroma Italian herbs yang harum berpadu dengan keju quick melt dan parmesan, menciptakan sajian hangat, gurih, dan begitu menggoda yang siap disantap seluruh anggota keluarga. Mudah dibuat, kaya protein, dan pastinya jadi comfort food andalan yang bikin siapa pun ketagihan.' WHERE id = 95;
UPDATE public.recipes SET description = 'Manis gurihnya tempe yang lembut berpadu sempurna dengan bumbu ulek segar beraroma khas, menciptakan hidangan rumahan yang begitu menggoda. Sentuhan kecap manis dan irisan cabe ijo membuat setiap suapan terasa nikmat, hangat, dan selalu bikin nambah nasi.' WHERE id = 96;
UPDATE public.recipes SET description = 'Tempe Melet mempersembahkan sensasi gurih tempe yang dibelah dan diisi tumisan sambal pedas menggoda, lalu dibalut tepung renyah bercita rasa. Begitu digigit, pedasnya langsung meletup di mulut, memberikan kejutan lezat yang disukai seluruh anggota keluarga.' WHERE id = 97;
UPDATE public.recipes SET description = 'Tempe goreng renyah berbalut tepung bumbu gurih ini menyembunyikan isian sambal pedas segar yang ditumis dengan tomat, bawang, dan wangi kemangi. Setiap gigitannya memadukan kriuk di luar dan ledakan rasa pedas gurih di dalam, camilan hangat yang pasti disukai seluruh keluarga!' WHERE id = 98;
UPDATE public.recipes SET description = 'Lodeh TKL menghadirkan semangkuk penuh kehangatan berisi tempe gurih, kacang panjang segar, dan labu siam lembut yang berpadu dalam kuah santan kuning rempah. Aroma tumis bawang dan kunyit berbisik lembut, menjanjikan rasa rumahan yang selalu bikin ketagihan. Sajikan hangat-hangat untuk senyum bahagia di meja makan keluarga Anda!' WHERE id = 100;
UPDATE public.recipes SET description = 'Nikmati kerenyahan tiada tara dari Keripik Tempe Sagu Tani, camilan renyah dan gurih hasil fermentasi alami calon tempe yang dibalut tepung sagu pilihan. Setiap iris tipisnya menciptakan sensasi garing berpadu lembut, dengan sentuhan gurih bawang putih yang begitu menggoda selera. Sajian istimewa buatan sendiri ini siap menemani momen kumpul keluarga, sekali coba pasti nagih!' WHERE id = 102;
UPDATE public.recipes SET description = 'Orek tempe tahu menghadirkan harmoni sempurna tempe dan tahu goreng berpadu bumbu kuning yang harum, gurihnya kecap manis, dan sedikit pedas yang menggoda. Setiap suapan terasa lembut, meresap bumbu hingga ke dalam, menjadikannya lauk favorit yang selalu mengundang senyum seluruh anggota keluarga. Sajian sederhana nan kaya protein ini pas untuk melengkapi hari-hari penuh cerita di meja makan.' WHERE id = 103;
UPDATE public.recipes SET description = 'Nikmati kelezatan Perkedel Tempe buatan sendiri yang renyah di luar dan lembut di dalam, dengan aroma harum bawang goreng dan seledri yang menggoda selera. Setiap gigitan menghadirkan rasa gurih yang pas, cocok jadi teman setia nasi hangat atau camilan sore yang disukai seluruh anggota keluarga. Sekali coba, pasti minta tambah lagi!' WHERE id = 104;
UPDATE public.recipes SET description = 'Bakso Tempe yang kenyal dan gurih ini adalah sajian penuh cinta yang memadukan kelezatan tempe pilihan dengan bumbu sederhana, menciptakan camilan sehat yang disukai seluruh anggota keluarga. Cocok disantap dengan kuah kaldu hangat, siraman bumbu kacang, atau sekadar dibakar bersama kecap manis, setiap gigitannya menghadirkan kebahagiaan di meja makan.' WHERE id = 105;
UPDATE public.recipes SET description = 'Tumis Tempe Kemangi menghadirkan perpaduan tempe goreng gurih bertekstur renyah di luar dengan sambal pedas beraroma kencur yang menggoda dan kesegaran daun kemangi. Setiap suapannya memanjakan lidah dengan ledakan rasa pedas sedap yang bikin semangat makan nasi hangat, pas menjadi lauk favorit sekeluarga.' WHERE id = 106;
UPDATE public.recipes SET description = 'Tempe goreng telur ini menyajikan stik tempe lembut berbalut lapisan telur dan tepung yang renyah gurih, menciptakan perpaduan tekstur yang bikin nagih. Disantap hangat-hangat dengan cocolan saus sambal, jadilah camilan sederhana favorit seluruh keluarga yang penuh cita rasa rumahan.' WHERE id = 107;
UPDATE public.recipes SET description = 'Tempe Jontor, kreasi unik tempe yang dilubangi lalu diisi racikan bumbu kencur dan cabe rawit, dibalut adonan tepung renyah, lalu digoreng hingga garing keemasan. Gigitan pertama langsung bikin ketagihan: gurih, sedikit pedas hangat, dan kriuk di luar namun lembut di dalam. Camilan sederhana yang dijamin ludes sekejap menjadi rebutan seluruh keluarga!' WHERE id = 109;
UPDATE public.recipes SET description = 'Tempe Kemul hadir dengan balutan tepung mendoan renyah yang berselimut aroma kunyit menggoda dan cita rasa segar daun kucai. Gigitan pertama dijamin bikin seluruh keluarga ketagihan, cocok jadi camilan hangat maupun lauk spesial di meja makan.' WHERE id = 111;
UPDATE public.recipes SET description = 'Tempe goreng berbalur bumbu karamel gurih dari gula merah dan kecap manis ini dipanggang di atas bara hingga aromanya menggugah selera. Sate Tempe yang renyah di luar dan lembut di dalam ini siap menjadi lauk favorit keluarga, apalagi ditemani taburan cabai, irisan bawang, dan siraman kecap manis kesukaan si kecil. Sajikan hangat-hangat, dijamin semua berebut minta tambah!' WHERE id = 113;
UPDATE public.recipes SET description = 'Tempe Kering Teri Medan menyuguhkan perpaduan sempurna tempe renyah dan teri gurih yang berpadu dalam balutan bumbu pedas manis beraroma daun jeruk. Setiap suapannya menghadirkan sensasi kriuk yang membangkitkan selera, pas sekali disandingkan dengan nasi putih hangat untuk santapan keluarga tercinta. Lauk praktis yang dijamin bakal jadi rebutan dan bikin makan siang semakin istimewa!' WHERE id = 114;
UPDATE public.recipes SET description = 'Sempol udang kenyal berpadu sempurna dengan gurihnya lapisan telur yang renyah di luar, lembut di dalam. Camilan rumahan yang bikin seluruh anggota keluarga berebut, makin istimewa dicocol saus sambal pedas-manis!' WHERE id = 116;
UPDATE public.recipes SET description = 'Rasakan kenikmatan udang bakar rumahan dengan olesan kecap manis legit dan sentuhan pedas yang pas, dijamin bikin seluruh keluarga lahap menyantapnya. Daging udang tetap empuk juicy berkat trik lumuran tepung tapioka, lalu dibakar hingga harum menggoda—menu spesial yang mudah dibuat dan selalu jadi rebutan di meja makan.' WHERE id = 117;
UPDATE public.recipes SET description = 'Paduan udang segar berukuran besar yang juicy berpadu sempurna dengan kuah asam pedas menyegarkan dari belimbing sayur dan tomat hijau, menciptakan sensasi segar dan pedas yang pas di lidah. Masakan rumahan ini mudah dibuat, menghadirkan cita rasa asli Indonesia yang menggugah selera dan cocok dinikmati bersama nasi putih hangat untuk makan siang keluarga.' WHERE id = 118;
UPDATE public.recipes SET description = 'Nikmati kelembutan siomay udang ayam rumahan yang padat gurih, berpadu manis renyahnya wortel di atas kulit tipis kenyal. Camilan hangat penuh cinta ini selalu sukses menciptakan momen kumpul keluarga yang lebih meriah dan sehat.' WHERE id = 119;
UPDATE public.recipes SET description = 'Siomay Ayam Udang ini menghadirkan perpaduan sempurna dari daging ayam dan udang segar yang lembut, dipadu labu siam untuk sensasi gigitan yang kenyal namun tidak keras saat dingin. Disajikan hangat bersama siraman bumbu kacang kental, kecap manis, dan sambal pedas, setiap suapan terasa gurih dan nikmat di lidah. Camilan sehat buatan sendiri ini dijamin jadi favorit keluarga untuk teman kumpul santai di akhir pekan.' WHERE id = 120;
UPDATE public.recipes SET description = 'Sambal Goreng Udang Lokio menghadirkan paduan sempurna udang segar yang manis gurih dengan aroma khas lokio yang menggugah selera. Tumisan cabai merah dan terasi yang pedas gurih berpadu dengan tomat segar, menciptakan hidangan nikmat dan hangat yang pasti disukai seluruh keluarga. Sajikan dengan nasi putih mengepul untuk makan siang yang istimewa dan penuh keceriaan.' WHERE id = 122;
UPDATE public.recipes SET description = 'Renyahnya peyek udang buatan sendiri dengan potongan udang segar yang juicy, sungguh menggoda! Aroma gurih santan dan bumbu rempah menggugah selera seisi rumah. Sajikan sebagai camilan spesial saat berkumpul bersama keluarga tercinta.' WHERE id = 123;
UPDATE public.recipes SET description = 'Sambel goreng udang pete ini memadukan udang segar yang digoreng setengah matang dengan sambal cabai merah yang pedas menggoda, menciptakan perpaduan rasa gurih, pedas, dan aroma khas pete yang menggugah selera. Setiap suapan menghadirkan tekstur kenyal udang, renyah pete, serta bumbu yang meresap sempurna, cocok disantap bersama nasi hangat untuk momen makan keluarga yang lebih istimewa.' WHERE id = 124;
UPDATE public.recipes SET description = 'Sajian Soto Udang Medan yang menggoda dengan kuah kaldu udang kental bersantan, diperkaya rempah pilihan seperti kunyit, jahe, dan serai, menghadirkan kehangatan di setiap suapan. Potongan udang segar, kol dan tauge yang renyah berpadu sempurna, menciptakan harmoni rasa gurih, segar, dan sedikit asam dari jeruk nipis. Cocok sebagai menu spesial untuk makan siang keluarga, dijamin seluruh anggota keluarga akan lahap menyantapnya!' WHERE id = 127;
UPDATE public.recipes SET description = 'Sensasi aglio olio klasik bertemu kelembutan keju dan udang windu segar yang juicy, menciptakan perpaduan rasa gurih, creamy, dan sedikit asam segar dari jeruk nipis yang begitu menggoda. Setiap suapan spaghetti kenyal berbalut butter harum bawang putih, taburan keju gurih, serta rempah Italia dan parsley renyah, langsung memanjakan lidah seluruh keluarga. Sajian rumahan yang cepat, mewah, dan aromanya bikin siapa pun tak sabar menyantapnya!' WHERE id = 129;
UPDATE public.recipes SET description = 'Nikmati kelezatan udang segar yang berpadu sempurna dengan siraman kecap manis legit dan sentuhan pedas yang menggugah selera. Aroma wangi tumisan rempah pilihan akan segera mengundang seluruh anggota keluarga berkumpul di meja makan. Sajian sederhana yang istimewa, dijamin bikin nasi putih cepat habis dan senyum ceria menghiasi wajah tercinta.' WHERE id = 130;
UPDATE public.recipes SET description = 'Nikmati kelezatan udang segar yang digoreng renyah, lalu ditumis dalam mentega harum bersama bawang bombay dan bawang putih yang menggoda selera. Sentuhan manis gurih dari kecap manis dan kecap inggris menciptakan hidangan simpel nan istimewa yang pasti disukai seluruh keluarga di rumah.' WHERE id = 131;
UPDATE public.recipes SET description = 'Sensasi udang segar berpadu dengan ledakan pedas khas Padang yang bikin semangat makan seisi rumah! Aroma bawang putih, jahe, dan daun jeruk yang ditumis harum langsung menggoda, lalu saus tiramnya meresap sempurna ke dalam daging udang yang juicy. Siap-siap nambah nasi, karena kuah pedas ekstra ini benar-benar nagih!' WHERE id = 132;
UPDATE public.recipes SET description = 'Nikmati semerbak aroma Timur Tengah yang hangat dan menggoda dari Nasi Kebuli buatan sendiri, di mana butiran nasi pulen menyerap sempurna kaldu rempah dan potongan daging kambing yang empuk berbumbu kari. Disajikan bersama telur dadar, emping renyah, dan taburan bawang goreng, hidangan ini menghadirkan kelezatan istimewa yang siap memanjakan seluruh keluarga di meja makan.' WHERE id = 139;
UPDATE public.recipes SET description = 'Sate kambing yang begitu empuk karena sentuhan nanas alami, dibalut bumbu rempah gurih dan kecap manis, lalu dibakar hingga harum menggoda. Sajikan selagi hangat dengan sambal kecap pedas-manis yang segar, dijamin seluruh keluarga akan ketagihan dari gigitan pertama!' WHERE id = 140;
UPDATE public.recipes SET description = 'Sate Kambing Tanpa Tusuk ini menghadirkan kelembutan daging yang juicy dengan balutan bumbu kecap manis legit dan sentuhan pedas yang menggoda, dijamin bikin seluruh keluarga ketagihan. Proses bakar lalu ungkep membuat bumbu meresap sempurna ke setiap serat daging, menghadirkan aroma bakaran yang mengundang seisi rumah untuk segera berkumpul. Sajian praktis nan lezat, hangat, dan penuh cinta untuk momen makan bersama tercinta.' WHERE id = 145;
UPDATE public.recipes SET description = 'Daging kambing empuk berpadu sempurna dengan rempah-rempah pilihan dan kuah segar tanpa santan, menciptakan cita rasa tongseng yang ringan namun tetap nendang. Sajian hangat ini kian menggoda dengan acar segar sebagai penyeimbang, cocok dinikmati bersama keluarga tercinta.' WHERE id = 146;
UPDATE public.recipes SET description = 'Tongseng Kambing yang empuk dan kaya rempah, berpadu manis gurihnya kuah kecap dengan segarnya irisan kol, tomat, dan bawang bombay. Pedas hangat dari cabe rawit menambah kenikmatan, menjadikannya hidangan sempurna untuk kebersamaan keluarga.' WHERE id = 148;
UPDATE public.recipes SET description = 'Nikmati kehangatan nasi Briyani dengan butiran Basmati pulen yang berselimut rempah pilihan, kunyit, kayu manis, dan sentuhan saffron kemerahan di tengahnya. Daging sapi atau kambing yang direbus perlahan dalam kaldu berbumbu begitu empuk dan meresap, membaur sempurna dengan harum kapulaga, cengkeh, dan daun mint. Sajian keluarga spesial ini dilengkapi taburan kismis manis, kacang mede renyah, dan acar segar—satu suapan langsung menghadirkan kehangatan dan kebahagiaan di meja makan!' WHERE id = 149;
UPDATE public.recipes SET description = 'Nikmati kelezatan Tahu Buncis Kuah Santan yang memadukan lembutnya tahu pong goreng, kerenyahan buncis segar, dan kuah santan gurih beraroma rempah daun jeruk serta serai. Sentuhan pedas cabai rawit utuh berpadu taburan bawang goreng membuat setiap suapan terasa hangat dan menggugah selera, cocok melengkapi makan siang keluarga tercinta. Sajikan bersama nasi putih hangat atau lontong agar kenikmatannya makin sempurna.' WHERE id = 150;
UPDATE public.recipes SET description = 'Manis legit kecap manis meresap sempurna ke dalam daging kambing yang empuk, berpadu pedas menggoda dari cabe rawit dan aroma hangat jahe yang menggugah selera. Setiap suapan Kambing Kecap ini menghadirkan kenikmatan gurih-manis yang pas, lengkap dengan taburan bawang goreng renyah, siap menjadi favorit seluruh keluarga di meja makan.' WHERE id = 151;
UPDATE public.recipes SET description = 'Nikmati kelezatan Nasi Goreng Kambing yang kaya rempah, perpaduan sempurna daging kambing kari yang empuk meresap dan nasi goreng gurih manis beraroma kayu manis dan kapulaga. Taburan bawang merah goreng yang melimpah, ditambah kesegaran acar timun dan renyahnya emping, membuat setiap suapan begitu istimewa. Sajian hangat yang selalu menggoda dan cocok dinikmati bersama keluarga tercinta.' WHERE id = 152;
UPDATE public.recipes SET description = 'Gulai kambing istimewa ini memadukan daging dan jeroan super empuk dalam limpahan santan gurih yang diperkaya rempah pilihan seperti kapulaga, cengkeh, dan kayu manis, menciptakan aroma hangat yang langsung membangkitkan selera. Cocok disantap bersama keluarga tercinta, setiap suapan kuah mengentalnya meresap sempurna menghadirkan kenikmatan Nusantara yang sulit dilupakan.' WHERE id = 154;
UPDATE public.recipes SET description = 'Machboos al Laham menghadirkan sejuta pesona rempah Timur Tengah dalam sepiring nasi kebuli kambing yang pulen, harum, dan kaya rasa. Potongan daging kambingnya begitu empuk meresap, berpadu manis alami kismis dan renyah bawang goreng yang membuat setiap suapan terasa istimewa. Sajian hangat nan mewah ini pasti jadi rebutan seluruh keluarga di meja makan.' WHERE id = 155;
UPDATE public.recipes SET description = 'Lapis daging sapi ini menghadirkan potongan daging dalam yang empuk meresap dalam balutan bumbu rempah pilihan—manis gurih dari gula merah, kecap, dan asam jawa berpadu harum dengan kayumanis, cengkih, serta pala. Setiap suapannya begitu menggoda dengan aroma serai dan daun jeruk yang membangkitkan selera, sempurna menemani nasi hangat sebagai hidangan utama favorit seluruh keluarga.' WHERE id = 158;
UPDATE public.recipes SET description = 'Japchae Korea buatan sendiri ini menghadirkan perpaduan bihun kenyal, irisan daging sapi yang gurih empuk, dan aneka sayuran segar dalam balutan bumbu manis gurih beraroma minyak wijen. Suapan demi suapan terasa ringan namun kaya rasa, cocok disajikan hangat sebagai menu spesial yang disukai seluruh anggota keluarga. Taburan wijen di atasnya menambah tekstur renyah yang bikin nagih!' WHERE id = 161;
UPDATE public.recipes SET description = 'Nikmati semangkuk sup daging sapi bening yang gurih alami, dengan potongan daging empuk, sayuran segar, dan aroma rempah yang hangat—dijamin anti gagal untuk pemula! Perasan jeruk limo menambahkan kesegaran yang membangkitkan selera, cocok sebagai menu makan siang keluarga yang simpel dan istimewa.' WHERE id = 162;
UPDATE public.recipes SET description = 'Serundeng Daging Sapi olahan istimewa ini menghadirkan perpaduan daging empuk berbumbu dan kelapa sangrai yang gurih kriuk, dimasak perlahan hingga warna cokelat keemasan menggoda. Aroma harum rempah, daun jeruk, dan serai berpadu sempurna, menjadikannya lauk kering favorit yang bikin keluarga lahap menyantap nasi hangat.' WHERE id = 163;
UPDATE public.recipes SET description = 'Rahasia bakso sapi super kenyal nan lembut ala rumahan ada pada paduan daging segar dan es batu yang diblender halus hingga menghasilkan tekstur melenting sempurna. Setiap butir bulat mulusnya terasa gurih alami, semakin istimewa saat berenang di kuah kaldu tulang hangat yang memanjakan seluruh keluarga.' WHERE id = 164;
UPDATE public.recipes SET description = 'Sensasi Gyudon rumahan yang lebih sehat hadir dengan paduan irisan daging sapi juicy, tahu lembut, dan bawang bombai manis yang dimasak dalam siraman kecap Jepang serta jus apel alami. Sekali masak, tercipta semangkuk kelezatan berprotein lengkap dan rendah lemak yang pasti disukai seluruh anggota keluarga tercinta.' WHERE id = 165;
UPDATE public.recipes SET description = 'Nikmati kelezatan Nasi Kebuli Daging Sapi yang gurih kaya rempah, dengan daging empuk dan aroma kari, kayu manis, serta kapulaga yang menggoda. Hidangan istimewa ini begitu nikmat disantap hangat bersama mentimun segar, telur dadar, dan sambal favorit keluarga.' WHERE id = 167;
UPDATE public.recipes SET description = 'Manjakan keluarga di rumah dengan Bulgogi, semur daging sapi ala Korea yang manis, gurih, dan begitu empuk berkat irisan daging tipis yang direndam dalam racikan kecap, madu, dan aroma minyak wijen yang memikat. Setiap suapan menghadirirkan rasa legit karamel alami yang berpadu sempurna dengan gurihnya daging panggang dan taburan wijen sangrai, sungguh pengalaman makan yang membuat semua orang kembali menambah nasi. Sajian hangat yang mudah dibuat ini dijamin jadi favorit baru di meja makan Anda!' WHERE id = 168;
UPDATE public.recipes SET description = 'Nikmati kelezatan kikil sapi kenyal yang dibalut bumbu urap kelapa sangrai gurih dan rempah pilihan. Aroma daun salam dan sereh menyatu sempurna dengan pedas manis yang ringan, menjadikan setiap suapan begitu menggoda selera. Hidangan sederhana yang cocok dinikmati seluruh keluarga, bikin nasi hangat makin lahap!' WHERE id = 170;
UPDATE public.recipes SET description = 'Hangatnya semangkuk Sup Iga dan Daging Sapi ini langsung memeluk keluarga dengan kaldu bening kaya rempah yang meresap hingga ke sumsum. Iga dan potongan daging sapi yang dimasak perlahan begitu empuk dan gurih, berpadu dengan wangi rempah pilihan seperti kayu manis dan pala, menciptakan rasa rumahan yang menenangkan jiwa. Taburan daun seledri, bawang goreng, serta perasan jeruk nipis dan sambal membuat setiap suapannya semakin segar dan menggoda—cocok jadi hidangan istimewa untuk melengkapi kehangatan di meja makan Anda.' WHERE id = 172;
UPDATE public.recipes SET description = 'Nikmati kelezatan Beef Teriyaki ala Hokben yang mudah dibuat di rumah, dengan irisan daging sapi empuk berpadu manis gurih saus teriyaki, saus tiram, dan sentuhan jahe. Disajikan hangat bersama nasi putih mengepul, potongan cabai hijau dan bawang bombay segar, hidangan ini jadi favorit keluarga yang selalu bikin nambah.' WHERE id = 173;
UPDATE public.recipes SET description = 'Sajikan kelezatan ala restoran di meja makan Anda dengan beef patty steak lada hitam yang juicy dan empuk, disiram saus lada hitam kental yang kaya rasa pedas manis. Lengkapi dengan kentang goreng renyah berbalut tepung maizena, jadikan momen spesial keluarga terasa hangat dan memuaskan.' WHERE id = 175;
